const a={configTemplates:{intro:{t:0,b:{t:2,i:[{t:3}],s:"Yapıştırmaya hazır Klipper yapılandırma blokları ve makrolar - başlangıç dizileri, filament işleme, giriş şekillendirme, tabla ağı ve daha fazlası. Birini kopyalayıp printer.cfg dosyanıza ekleyin (Yapılandırma Düzenleyici yapıştırmak için iyi bir yerdir)."}},help:{guide:{t:0,b:{t:2,i:[{t:3}],s:"Yardım"}},guideTitle:{t:0,b:{t:2,i:[{t:3}],s:"Yapılandırma Şablonları Hakkında"}},close:{t:0,b:{t:2,i:[{t:3}],s:"Kapat"}},howToRead:{t:0,b:{t:2,i:[{t:3}],s:"Nasıl kullanılır"}},steps:[{t:0,b:{t:2,i:[{t:3}],s:"Bir makro veya yapılandırma bloğu bulmak için kategoriye göre filtreleyin."}},{t:0,b:{t:2,i:[{t:3}],s:"Açıklamayı ve hangi bölümlere ihtiyaç duyduğunu okuyun."}},{t:0,b:{t:2,i:[{t:3}],s:"Şablonu kopyalayın, yapılandırmanıza yapıştırın ve değerleri ayarlayın."}}],topics:{what:{title:{t:0,b:{t:2,i:[{t:3}],s:"Bunlar nedir"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Yaygın Klipper yapı taşlarından özenle seçilmiş bir set: gcode_macros (PRINT_START, PAUSE/RESUME, filament yükleme/boşaltma, M600) ve yapılandırma bölümleri ([input_shaper], [bed_mesh], [firmware_retraction], …). Bunlar başlangıç noktalarıdır - her birini okuyun ve makineniz için ince ayarını yapın."}}},insert:{title:{t:0,b:{t:2,i:[{t:3}],s:"Bir şablon ekleme"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Bir şablonu kopyalayın, ardından printer.cfg dosyanıza yapıştırın - Yapılandırma Düzenleyici'nin Ham görünümü uygun bir noktadır. Kaydettikten sonra bir donanım yazılımı yeniden başlatması bunu uygular. Değerleri her zaman önce gözden geçirin; buradaki varsayılanlar makuldür ama yazıcınıza göre ince ayarlanmamıştır."}}},sections:{title:{t:0,b:{t:2,i:[{t:3}],s:"Gerekli bölümler"}},body:{t:0,b:{t:2,i:[{t:3}],s:"Her şablon, tanımladığı veya bağımlı olduğu yapılandırma bölümlerini listeler. Bir bölüm yapılandırmanızda zaten varsa, yinelenen bir kopya yapıştırmak yerine anahtarları birleştirin (yinelenen bir bölüm başlangıçta reddedilir)."}}},glossary:{title:{t:0,b:{t:2,i:[{t:3}],s:"Sözlük"}},body:{t:0,b:{static:"",t:2,i:[]}}}},glossary:{template:{term:{t:0,b:{t:2,i:[{t:3}],s:"Şablon"}},def:{t:0,b:{t:2,i:[{t:3}],s:"printer.cfg dosyasına kopyaladığınız, yapıştırmaya hazır bir Klipper yapılandırma veya makro G-code parçacığı."}}},macro:{term:{t:0,b:{t:2,i:[{t:3}],s:"gcode_macro"}},def:{t:0,b:{t:2,i:[{t:3}],s:"Bir G-code dizisi çalıştıran, yapılandırmada tanımladığınız adlandırılmış bir komut (örn. PRINT_START)."}}},section:{term:{t:0,b:{t:2,i:[{t:3}],s:"Bölüm"}},def:{t:0,b:{t:2,i:[{t:3}],s:"[köşeli parantezli] bir yapılandırma bloğu, örn. [bed_mesh] - Klipper yapılandırmasının gruplandığı birim."}}}}},category:{label:{t:0,b:{t:2,i:[{t:3}],s:"Kategori"}},all:{t:0,b:{t:2,i:[{t:3}],s:"Tüm kategoriler"}}},template:{copy:{t:0,b:{t:2,i:[{t:3}],s:"Kopyala"}},copied:{t:0,b:{t:2,i:[{t:3}],s:"Kopyalandı!"}},requires:{t:0,b:{t:2,i:[{t:3,v:"Bölümler: "},{t:4,k:"sections"}]}},requiresNone:{t:0,b:{t:2,i:[{t:3}],s:"-"}}},count:{t:0,b:{t:2,i:[{t:4,k:"n"},{t:3,v:" şablon"}]}},states:{loading:{t:0,b:{t:2,i:[{t:3}],s:"Şablonlar yükleniyor…"}},error:{t:0,b:{t:2,i:[{t:3}],s:"Şablonlar yüklenemedi."}},empty:{t:0,b:{t:2,i:[{t:3}],s:"Bu kategoride şablon yok."}},retry:{t:0,b:{t:2,i:[{t:3}],s:"Yeniden dene"}}},categories:{config_blocks:{t:0,b:{t:2,i:[{t:3}],s:"Yapılandırma blokları"}},macros:{t:0,b:{t:2,i:[{t:3}],s:"Makrolar"}}}}};export{a as default};
